import{_ as a}from"./chunks/single_macro_morph_armed.CtViY7QV.js";import{_ as s,C as r,o as h,c as i,a3 as g,E as l,w as p,j as t,a as n}from"./chunks/framework.hkNkIkN3.js";const d="/versions/v0.19.10/screens/snapshots/knob_bank_morph.png",S=JSON.parse('{"title":"Morph","description":"","frontmatter":{},"headers":[],"relativePath":"snapshots/morph.md","filePath":"snapshots/morph.md"}'),c={name:"snapshots/morph.md"};function m(u,o,f,k,b,w){const e=r("ManualRelated");return h(),i("div",null,[o[1]||(o[1]=g('<h1 id="morph" tabindex="-1">Morph <a class="header-anchor" href="#morph" aria-label="Permalink to &quot;Morph&quot;">​</a></h1><p>Occupied <strong>Select</strong> on a snapshot pad glides from <strong>what you are hearing</strong> to that pad. <strong>FADE TIME</strong> on that bank’s <strong>pencil</strong> is the glide length in musical time at project BPM. When fade is <strong>OFF</strong>, Select is instant. Arrange <strong>FADE TIME</strong> is only the song playhead.</p><p>MIDI, a mapped slot, a macro, and the Arrange <strong>playhead</strong> use the same glide. There are no <strong>SET MORPH A</strong> / <strong>SET MORPH B</strong> marks and no <strong>END MORPH</strong> row. Pads do not show A/B marks.</p><h2 id="start-a-morph" tabindex="-1">Start a morph <a class="header-anchor" href="#start-a-morph" aria-label="Permalink to &quot;Start a morph&quot;">​</a></h2><p>On any <strong>4×8</strong> (<a href="./knob-bank">knobs</a>, <a href="./lfo-bank">LFOs</a>, <a href="./rack-bank">racks</a>):</p><ul><li>Occupied <strong>Select</strong> starts (or continues) a morph <strong>live → that pad</strong> when <strong>this bank&#39;s FADE TIME</strong> is on. When <strong>this bank&#39;s FADE TIME</strong> is <strong>OFF</strong>, occupied Select lands instantly.</li><li><strong>Hold Select and turn the encoder</strong> on an occupied <strong>BANK</strong> pad to arm a morph from what you are hearing to that pad at <strong>0%</strong>. The first click arms <strong>and</strong> moves the blend. After a short hold the header mark becomes a circle and square so you can see that this hold is a blend, not a tap. This works with fade <strong>OFF</strong> (the clocked glide does not start). While a glide is already running, hold Select and turn still rides the amount. Turning past <strong>100%</strong> does not wrap back to 0% on the same hold, and 100% stays armed so you can turn back. Opening pad <strong>Options</strong> (keep holding Select) uses the encoder for the menu — it does not morph. Let go below 100% and the mix stays at that percent; hold Select and turn again to continue from there.</li><li>Another occupied pad while a glide is running <strong>retargets</strong> — it ends the current glide and starts a new one from the live sound to the new pad. You do not confirm <strong>END + RECALL</strong>. With fade <strong>OFF</strong>, retarget the blend pad by holding Select and turning on a different occupied pad — a tap still lands instantly.</li><li>The <strong>same</strong> pad you are already morphing toward does not restart a glide.</li><li>Empty pads <strong>TAKE</strong> (or dest-pick). They do not morph.</li><li><strong>Back</strong> on the 4×8 drops a manual morph without landing on the pad.</li></ul><p>While a morph is running, the <strong>pad you are blending toward</strong> shows a <strong>fader and percent as one group</strong> (after the pad number, with a little air from the index). Live is the near end; that pad is the far end. The header stays <strong>Knobs Snapshots</strong>. The fader stays the same width from <strong>0%</strong> to <strong>100%</strong> — only the percent text changes. The group hides about a second and a half after you stop turning, or after a mapped morph knob stops moving. Hold Select and turn again to continue from the last percent, including at <strong>0%</strong> or <strong>100%</strong>. Let go at 100% and that pad becomes the live snapshot. Arrange SONG still marks that column <code>K*</code> / <code>L*</code> / <code>R1*</code>…<code>R8*</code>.</p><p><img src="'+d+'" alt="Knob snapshot 4×8 while morphing" class="screen"></p><h2 id="sweep-the-amount" tabindex="-1">Sweep the amount <a class="header-anchor" href="#sweep-the-amount" aria-label="Permalink to &quot;Sweep the amount&quot;">​</a></h2><p>While a morph is running (including a hold-arm at 0% or 100%), <strong>hold Select and turn the encoder</strong> on that 4×8. A slow turn moves about <strong>1%</strong>; turning faster takes larger steps (the same slow/fast encoder feel as other values). <strong>0% is what you are hearing now</strong> — the physical knob once pickup has caught, or when pickup is off. If pickup has not caught, 0% stays on that catch; catching during a morph does not jump 0% to the knob and does not end the morph. <strong>100%</strong> is the target pad. Reaching 100% does <strong>not</strong> end the hold — turn back toward 0% to morph toward live again. Letting go at 100% lands the pad. Letting go below 100% keeps that percent so the next hold continues from there.</p><p>You can also <strong>map the amount</strong> from a knob or from MIDI CC / 14-bit CC (<strong>SETTINGS → MAPPING → MAP MORPH</strong>). That mapping is a fader from <strong>what you are hearing</strong> to the <strong>current snapshot</strong> on that bank — the same idea as a crossfader between two tracks, for MIDI and the other snapshot fields. You do not have to start a pad glide first. First motion arms live as the near end; 100% is the selected snapshot; <strong>0% follows live</strong> (hardware after catch), not a freeze from when the morph started. Recalling or taking a different snapshot aims the same fader at that scene. The mapping hub is titled <strong>MAP AMOUNT</strong> (Internal knob or External CC / 14-bit CC). Learn External with CC or 14-bit CC (not notes or a physical knob move). The mapped knob <strong>is</strong> the amount (plus optional <strong>MIN</strong> / <strong>MAX</strong> as 0–100% and <strong>INVERT</strong>). On the macro grid, <strong>PART</strong> reads <strong>KNOBS</strong>, <strong>LFOS</strong>, or <strong>RACK1</strong>…<strong>RACK8</strong>. Program Change and notes do not drive amount. An LFO cannot target morph amount (and still cannot target snapshot <strong>index</strong>). <strong>MAPPING → UNMAP MORPH</strong> removes that mapping.</p><p>Hold Select and turn on an occupied <strong>BANK</strong> pad still morphs toward <strong>that</strong> pad (a manual override). Empty banks do nothing.</p><p>A morph-amount knob is not rewritten when the knobs snapshot morphs or recalls — it stays the blend fader. Snapshot-slot and morph-amount macros do not show <strong>PICKUP</strong>. Pickup on other macros keeps the <strong>solid value line</strong> on the physical knob: <strong>dim</strong> until you catch, <strong>bright</strong> when you are in control. The <strong>dotted catch line</strong> is brighter. While an LFO is modulating that macro you can still catch when the mix is not moving; the LFO follows the catch as an offset. When the LFO sits on the catch, that LFO mark is dotted too.</p><p>A morph-amount macro on Perform reads <strong>MORPH</strong>, the bank (<strong>Knobs</strong>, <strong>LFOs</strong>, or the rack name), <strong>TO DROP</strong>, and <strong>42%</strong> on the right while that bank is morphing. Idle, the destination is the current snapshot on that bank. When only one or two macros are on, Perform gives it the taller layout — see <a href="./../perform/knob-view#snapshot-and-morph-knobs">Snapshot and morph knobs on Perform</a>.</p><p><img src="'+a+'" alt="Morph knob packed on Perform" class="screen"></p><ul><li><strong>0–49%:</strong> discrete fields and the whole Step Seq pattern stay on live (A).</li><li><strong>50–100%:</strong> those fields jump to the target pad.</li></ul><p>Continuous values move smoothly the whole way: pot positions, LFO rate / depth / phase / offset, and device parameters that have a real range (not enums, notes, or channels).</p><p><strong>INCLUDE</strong> on the target slot still applies. A fade uses that slot’s include list — excluded live values stay put. Morph only moves knobs macros / LFOs / rack devices that are included on the target. <strong>ALLOW MORPH NO</strong> is a separate skip during the fade.</p><p>A parameter set to <strong>IN SNAPSHOT OFF</strong> is skipped by a morph at <strong>every</strong> position, including the ends. See <a href="./#keep-one-parameter-under-your-hands">Keep one parameter under your hands</a>.</p><p>A parameter set to <strong>ALLOW MORPH NO</strong> (with <strong>IN SNAPSHOT ON</strong>) stays live during the fade and jumps to the snapshot at <strong>100%</strong>. It does not lerp.</p><p>MIDI is sent only when a value changes, using the same pickup rules as a recall: the morph output is the logical value; physical knobs still have to catch up.</p><p>The Step Seq <strong>playhead keeps running</strong>. Morphing does not emit a new note for every in-between pattern — the pattern swaps as a whole at 50%.</p><h2 id="fade-time" tabindex="-1">Fade Time <a class="header-anchor" href="#fade-time" aria-label="Permalink to &quot;Fade Time&quot;">​</a></h2><p><strong>FADE TIME</strong> on that bank’s <strong>pencil</strong> sets how a pad / MIDI / SNAP-macro recall lerps into the target slot, in musical time at the project BPM: <strong>OFF</strong> (instant, default), then <strong>1/16</strong>, <strong>1/8</strong>, <strong>1/4</strong>, <strong>1/2</strong>, <strong>1 BAR</strong>, <strong>2 BARS</strong>, <strong>4 BARS</strong>. Hold Select and turn the encoder to change it. Arrange <strong>pencil → FADE TIME</strong> is only how the <strong>playhead</strong> glides — it does not change pad recalls.</p><ul><li>A recall from Main Menu Snapshots, a mapped slot, or a macro uses <strong>that bank’s</strong> FADE TIME. The Arrange <strong>playhead</strong> uses Arrange FADE TIME. Both glides use the same live 0% as encoder / MAP MORPH — they do not freeze a past mix when the fade arms.</li><li>When <strong>this bank&#39;s FADE TIME</strong> is <strong>OFF</strong>, occupied Select is instant. You can still morph by holding Select and turning the encoder on that pad.</li><li>Take and delete on that bank wait until the fade finishes.</li><li><a href="./lanes">Arrange</a> <strong>Jump To</strong> and <strong>Queue</strong> stay instant. Jump To aborts an in-progress fade by snapping to the fade target, then jumps. Queue cancels the fade without snapping, then the queue can fire.</li></ul><p>A knob or MIDI mapping can still step a <strong>snapshot slot index</strong> (<strong>SETTINGS → MAPPING → MAP SNAPSHOT</strong>). <strong>MAP MORPH</strong> is the blend-amount mapping under the same <strong>MAPPING</strong> row — not a second destination pad.</p>',26)),l(e,null,{default:p(()=>[...o[0]||(o[0]=[t("ul",null,[t("li",null,[t("a",{href:"./knob-bank"},"Knob snapshots"),n(" — Occupied Select on the 4×8")]),t("li",null,[t("a",{href:"./rack-bank"},"Rack snapshots"),n(" — Morph from a rack pad")]),t("li",null,[t("a",{href:"./lfo-bank"},"LFO snapshots"),n(" — Morph from an LFO pad")]),t("li",null,[t("a",{href:"./lanes"},"Arrange"),n(" — Clocked recall; Jump To / Queue stay instant")]),t("li",null,[t("a",{href:"./"},"Snapshots"),n(" — Snapshot overview")])],-1)])]),_:1})])}const M=s(c,[["render",m]]);export{S as __pageData,M as default};
